<?php
declare(strict_types=1);
require_once __DIR__.'/onboarding.php';
function migration_action(array $input): never {
    if(array_diff(array_keys($input),['action','csrf','op','target','revision','confirmation'])){throw new InputError('Nepovolené pole přesunu.');}
    $op=field($input,'op',20);$revision=field($input,'revision',10);
    if(!in_array($op,['check','create','move','write','restart'],true)||!ctype_digit($revision)||($input['confirmation']??'')!=='1'){throw new InputError('Potvrďte konkrétní operaci.');}
    onboarding_rpc(['kind'=>'migration_'.$op,'target'=>field($input,'target',40),'revision'=>(int)$revision,'confirmation'=>true]);
    header('Location: /?migration=1',true,303);exit;
}
function migration_form(string $op,string $target,int $revision,string $csrf,string $label): void { ?>
<form method="post" action="/?migration=1"><input type="hidden" name="action" value="migration-action"><input type="hidden" name="op" value="<?=e($op)?>"><input type="hidden" name="target" value="<?=e($target)?>"><input type="hidden" name="revision" value="<?=$revision?>"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><label class="check"><input type="checkbox" name="confirmation" value="1" required>Potvrzuji: <?=e($label)?></label><button><?=e($label)?></button></form>
<?php }
function serve_migration(string $csrf,string $error): never {
    $state=null;$nodes=[];
    try{$result=onboarding_rpc(['kind'=>'migration_view']);$state=$result['job'];$nodes=$result['nodes'];}catch(Throwable $e){$error=$error?:'Služba přesunu není dostupná. Žádný nový přesun nebyl potvrzen.';}
    $phase=$state['phase']??'UNKNOWN';$pending=in_array($phase,['CHECKING','CREATING','MOVING','WRITING','RESTARTING'],true);
    $labels=['IDLE'=>'Vyberte server pro testovací aplikaci','CHECKING'=>'Ověřujeme cílový server','READY'=>'Kontrola cíle dokončena','CREATING'=>'Zakládáme testovací aplikaci','RUNNING'=>'Aplikace běží a data jsou ověřená','MOVING'=>'Přenášíme aplikaci a její data','WRITING'=>'Zapisujeme testovací data','RESTARTING'=>'Ověřujeme data po restartu aplikace','NEEDS_REVIEW'=>'Přesun vyžaduje kontrolu'];
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FallbackHosting · Přesun aplikací</title><link rel="stylesheet" href="/admin.css"><?php if($pending):?><meta http-equiv="refresh" content="3"><?php endif;?></head><body><header><a class="brand" href="/">F/ FallbackHosting</a><a href="/">Servery</a><a href="/?install=1">Aplikace</a><a href="/?center=index.html">Řídicí centrum</a><form method="post" action="/"><input type="hidden" name="action" value="logout"><input type="hidden" name="csrf" value="<?=e($csrf)?>"><button class="quiet">Odhlásit</button></form></header><main><section class="heading"><p class="eyebrow">APLIKACE / PŘESUN MEZI SERVERY</p><h1>Přesun aplikací</h1><p>První ověřovaný typ: vlastní testovací Redis a web se dvěma datovými svazky. Přesun skutečných produkčních aplikací zatím není dostupný.</p></section>
<?php if($error!==''):?><p class="alert" role="alert"><?=e($error)?></p><?php endif;?>
<?php if($state):?><section class="panel"><h2><?=e($labels[$phase]??'Neznámý stav')?></h2><p>Záznam <?=e($state['utc'])?> UTC</p>
<?php if(isset($state['current'])):?><dl><dt>Aplikace</dt><dd>Test Redis + soubory</dd><dt>Aktuální server</dt><dd><?=e($state['current']['node'])?></dd><dt>Ověřená hodnota v databázi i webovém souboru</dt><dd><?=e($state['verification']['counter']??'Neověřeno')?></dd><dt>Dokončené přesuny</dt><dd><?=count($state['transfers']??[])?></dd></dl><p>Aplikace je izolovaná bez veřejného portu. Databázový klíč a obsah webu ověřujeme uvnitř jejích kontejnerů.</p><?php endif;?>
<?php if($phase==='NEEDS_REVIEW'):?><p class="alert">Operace byla přerušena nebo neprošla ověřením. Původní svazky a dostupnou zálohu zachováváme. Automatické opakování je zablokované; před obnovením provozu je nutné prověřit skutečný stav obou kopií.</p><?php endif;?>
<?php if($pending):?><p>Průběh se obnovuje automaticky. Při kopírování jsou zápisy testovací aplikace zastavené. Původní svazky zůstávají zachované.</p><?php endif;?>
<?php if($phase==='READY'&&isset($state['capacity'])):$c=$state['capacity'];?><h3>Cíl: <?=e($state['target'])?></h3><dl><dt>Docker</dt><dd><?=e($c['docker_version'])?></dd><dt>Architektura</dt><dd><?=e($c['architecture'])?></dd><dt>CPU</dt><dd><?=e($c['cpus'])?></dd><dt>Volná paměť</dt><dd><?=e((string)round($c['memory_available_bytes']/1073741824,2))?> GiB</dd><dt>Volné místo pro Docker svazky</dt><dd><?=e((string)round($c['disk_available_bytes']/1073741824,2))?> GiB</dd><dt>Existující kontejnery</dt><dd><?=e($c['containers'])?></dd><dt>Okamžitá spotřeba CPU kontejnerů</dt><dd><?=e((string)$c['current_container_cpu_percent'])?> % (100 % = jedno jádro)</dd><dt>Historické maximum</dt><dd>Neznámé — není doložená historie měření</dd><dt>Požadavek testovací aplikace</dt><dd>256 MiB dostupné paměti; nejméně 512 MiB volného disku. Každý ze dvou kontejnerů má limit 96 MiB a 0,25 CPU.</dd></dl>
<?php if($state['readiness']):?><p>Naměřená kapacita pro tuto malou testovací aplikaci vyhovuje. Pro produkční aplikace bude nutný jejich vlastní odhad dat a zátěže.</p><?php migration_form(isset($state['current'])?'move':'create',$state['target'],$state['revision'],$csrf,isset($state['current'])?'Přesunout testovací aplikaci na '.$state['target']:'Vytvořit testovací aplikaci na '.$state['target']);?>
<?php else:?><p class="alert">Naměřená kapacita nestačí. Vytvoření ani přesun nelze spustit.</p><?php endif;endif;?>
<?php if(in_array($phase,['IDLE','READY','RUNNING'],true)):?><h3><?=isset($state['current'])?'Vybrat cíl přesunu':'Vybrat server'?></h3><p>Nejprve ověříme dostupnost Dockeru, současné zatížení a místo. Kontrola nic neinstaluje ani nerestartuje.</p><?php foreach($nodes as $node):if(($state['current']['node']??'')===$node){continue;}migration_form('check',$node,$state['revision'],$csrf,'Prověřit cíl '.$node);endforeach;?>
<?php if(isset($state['current'])):migration_form('write',$state['current']['node'],$state['revision'],$csrf,'Přidat testovací záznam');migration_form('restart',$state['current']['node'],$state['revision'],$csrf,'Ověřit data po restartu testovací aplikace');endif;endif;?></section>
<?php if(!empty($state['transfers'])):?><section class="panel"><h2>Ověřené přesuny</h2><?php foreach($state['transfers'] as $transfer):?><p><?=e($transfer['source'])?> → <?=e($transfer['target'])?> · <?=e($transfer['utc'])?> UTC · databáze i soubory: <?=e($transfer['verification']['counter'])?> · kontrolní součty a obnovená data souhlasí</p><?php endforeach;?></section><?php endif;endif;?></main><footer>FallbackHosting · ověřená kopie · zachovaná původní data</footer></body></html><?php exit;
}
